export type BuyerInvoice = { /** What the buyer can do with the invoice: pay. pay is available when a checkout session can take a payment now, and then required, due by due_at or by the due date of the installment it collects. */ "buyer_actions": Array<BuyerAction>; "cc_emails"?: Array<string>; /** RFC3339 timestamp. Format: date-time. */ "closed_at"?: string; "collection_block_status": "none" | "inventory_blocked" | "resolved" | (string & {}); /** RFC3339 timestamp. Format: date-time. */ "created_at"?: string; /** Monetary amount represented as integer minor units plus an ISO 4217 currency code. */ "credit_money": MoneyValue; /** Monetary amount represented as integer minor units plus an ISO 4217 currency code. */ "currently_due_money": MoneyValue; "customer"?: (({ /** RFC3339 timestamp. Format: date-time. */ "created_at"?: string; "customer_id": string; "email": string; "name"?: string; "phone"?: string; /** RFC3339 timestamp. Format: date-time. */ "updated_at"?: string; }) | (null)); "customer_id"?: string; /** RFC3339 timestamp. Format: date-time. */ "due_at"?: string; "footer"?: string; "invoice_id": string; /** Sequential document number assigned when the invoice is issued. Numbering is per merchant, with test and live mode numbered independently. */ "invoice_number"?: string; "is_overdue": boolean; /** RFC3339 timestamp. Format: date-time. */ "issued_at"?: string; "late_fees": Array<BuyerInvoiceLateFee>; "memo"?: string; "merchant_id": string; "order"?: (({ /** RFC3339 timestamp. Format: date-time. */ "created_at"?: string; "customer_id"?: string; "fulfillment_status"?: "not_fulfilled" | "partially_fulfilled" | "fulfilled" | "canceled" | "not_applicable" | "closed" | (string & {}); "order_id": string; "order_number"?: string; "payment_intent_ids"?: Array<string>; "payment_status": "unpaid" | "partially_paid" | "paid" | (string & {}); "pricing_amounts": PricingAmounts; "refund_status": "none" | "partially_refunded" | "refunded" | (string & {}); "settlement_amounts": SettlementAmounts; "status": "open" | "closed" | (string & {}); /** RFC3339 timestamp. Format: date-time. */ "updated_at"?: string; }) | (null)); "order_id": string; /** Monetary amount represented as integer minor units plus an ISO 4217 currency code. */ "outstanding_money": MoneyValue; /** RFC3339 timestamp. Format: date-time. */ "paid_at"?: string; /** Monetary amount represented as integer minor units plus an ISO 4217 currency code. */ "paid_money": MoneyValue; "payment_terms_snapshot"?: InvoicePaymentTermsSnapshot; "po_number"?: string; "recipient_email"?: string; "reference"?: string; "refund_status": "none" | "partially_refunded" | "refunded" | (string & {}); /** Monetary amount represented as integer minor units plus an ISO 4217 currency code. */ "refunded_money": MoneyValue; "remit_to_address"?: PostalAddress; "schedule_entries"?: Array<InvoiceScheduleEntry>; /** RFC3339 timestamp. Format: date-time. */ "scheduled_send_at"?: string; /** RFC3339 timestamp. Format: date-time. */ "service_at"?: string; "snapshot"?: InvoiceSnapshot; "status": "draft" | "open" | "partially_paid" | "paid" | "void" | "uncollectible" | "credited" | (string & {}); "timezone"?: string; /** RFC3339 timestamp. Format: date-time. */ "updated_at"?: string; /** Current invoice version. Send this as expected_version when updating the draft. Use an exact numeric string, not a floating-point number. Format: int64. minimum: 1. */ "version": string; /** RFC3339 timestamp. Format: date-time. */ "viewed_at"?: string; /** RFC3339 timestamp. Format: date-time. */ "voided_at"?: string; };
